import React,{useState,useEffect} from "react";  
import axios from "axios";
import { Package,Truck,CheckCircle,Clock } from "lucide-react";
import './Dashboard.css';

const Dashboard = () => {
    const [bookings, setBookings] = useState([]);
    const [loading, setLoading] = useState(true);
   
    useEffect(() => {
        const fetchBookings = async () => {
            try { 
                const response = await axios.get("http://localhost:9023/api/parcels/all");
                setBookings(response.data);
            } catch (error) {
                console.error("Error fetching bookings:", error);
            }   finally {   
                setLoading(false);
            }       
        };
        fetchBookings();
    }, []);

    return (    
        <div className="dashboard-container">
            <div className="dashboard-header">
                <h2>welcome back,<span className="gold-text"></span></h2>
                <p>Manage your deliveries efficiently and track your parcel status in real-time.</p>
            </div>

            <div className="stats-grid">
                <div className="stat-card">
                    <Package className="icon-blue" />

                    <div>
                        <h3>{bookings.length}</h3>
                        <p>Total Bookings</p>
                    </div>
                </div>
                <div className="stat-card">
                    <Truck className="icon-gold" />
                    <div>
                        <h3>{bookings.filter((booking) => booking.status === "IN_TRANSIT").length}</h3>
                        <p>In Transit</p>
                    </div>
                </div>
                <div className="stat-card">
                    <CheckCircle className="icon-green" />
                    <div>
                        <h3>{bookings.filter((booking) => booking.status === "DELIVERED").length}</h3>
                        <p>Delivered</p>
                    </div>
                </div>
                </div> 
                <div className="recent-orders">
                    <div className="table-header">
                        <h3>Recent Bookings</h3>
                        <button className="view-all-btn">View All</button>
                    </div>
                    <div className="table-container">
                        <table>
                            <thead>
                                <tr>
                                    <th>Tracking ID</th>
                                    <th>Destination</th>
                                    <th>Vehicle</th>
                                    <th>Date</th>
                                    <th>Status</th>
                                </tr>
                            </thead>
                            <tbody>
                                {loading ? (
                                    <tr>
                                        <td colSpan="5">Loading orders...</td></tr>)
                                    :bookings.slice(0, 5).map((orders) => (
                                    <tr key={orders.tracking.id}>
                                        <td><strong>#{orders.tracking.id}</strong></td>
                                        <td>{orders.destinationAddress}</td>
                                        <td className="capitalize">{orders.vehicleType}</td>
                                        <td>{new Date(orders.bppkingDate).toLocaleDateString()}</td>
                                        <td>
                                            <span className={`status-badge ${orders.status?.toLowerCase()}`}>
                                                {orders.status}
                                            </span>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
    );
};

export default Dashboard;
